import sys
from collections import Counter

def solve(data):
    it=iter(data)
    N=int(next(it))
    A=[int(next(it)) for _ in range(N)]
    B=[int(next(it)) for _ in range(N)]
    knownA=[x for x in A if x!=-1]
    knownB=[x for x in B if x!=-1]
    both_known_sums=set()
    for a,b in zip(A,B):
        if a!=-1 and b!=-1:
            both_known_sums.add(a+b)
    if both_known_sums:
        if len(both_known_sums)!=1:
            return 'No'
        S=both_known_sums.pop()
    else:
        S=max(max(knownA) if knownA else 0,max(knownB) if knownB else 0,0)
    cntA=Counter(knownA)
    cntB=Counter(knownB)
    unknown_A_slots=N-len(knownA)
    unknown_B_slots=N-len(knownB)
    unmatched_known_A=0
    cntB_copy=cntB.copy()
    for a in knownA:
        need=S-a
        if cntB_copy.get(need,0)>0:
            cntB_copy[need]-=1
            if cntB_copy[need]==0:
                del cntB_copy[need]
        else:
            unmatched_known_A+=1
    unmatched_known_B=sum(cntB_copy.values())
    if unmatched_known_A<=unknown_B_slots and unmatched_known_B<=unknown_A_slots:
        return 'Yes'
    else:
        return 'No'
