        for c in range(26):
            cost=A[c]
            if cost<best_cost:
                second_cost=best_cost; second_c=best_c
                best_cost=cost; best_c=c
            elif cost<second_cost:
                second_cost=cost; second_c=c
        for prev_c in range(26):
            dp[i][prev_c][0]=best_cost
            dp[i][prev_c][1]=abs(ci-prev_c)+dp[i+1][prev_c][2]
            dp[i][prev_c][2]=abs(ci-prev_c)+dp[i+1][prev_c][3]
            cost_same=abs(ci-prev_c)+dp[i+1][prev_c][3]
            if best_c!=prev_c:
                cost_switch=best_cost
            else:
                cost_switch=second_cost
            dp[i][prev_c][3]=min(cost_same,cost_switch)
    min_cost=dp[0][0][0]
