            res.append(chr(97+chosen)); remaining-=abs(ci-chosen); prev_c=chosen; l=1
        elif l==1 or l==2:
            c=prev_c
            res.append(chr(97+c)); remaining-=abs(ci-c); l+=1
        else:
            cost_same=abs(ci-prev_c)+dp[i+1][prev_c][3]
            found=False; chosen=None
            for c in range(26):
                if c==prev_c: continue
                cost=abs(ci-c)+dp[i+1][c][1]
                if cost==remaining:
                    chosen=c; found=True; break
            if found:
                if chosen<prev_c:
                    res.append(chr(97+chosen)); remaining-=abs(ci-chosen); prev_c=chosen; l=1
                else:
                    res.append(chr(97+prev_c)); remaining-=abs(ci-prev_c); l=3
            else:
                res.append(chr(97+prev_c)); remaining-=abs(ci-prev_c); l=3
    return ''.join(res)

