import sys, math, bisect

def count_components(nums, threshold):
    n=len(nums)
    parent=list(range(n))
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]
            x=parent[x]
        return x
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb:
            parent[rb]=ra
    val_to_idx={v:i for i,v in enumerate(nums)}
    T=threshold
    present_small=[v for v in nums if v<=T]
    # SPF for up to T
    spf=[0]*(T+1)
    for i in range(2,T+1):
        if spf[i]==0:
            for j in range(i,T+1,i):
                if spf[j]==0:
                    spf[j]=i
    # function to get divisors
    def get_divisors(x):
        divs=[1]
        while x>1:
            p=spf[x]
            e=0
            while x%p==0:
                x//=p
                e+=1
            cur=len(divs)
            mul=1
            for k in range(e):
                mul*=p
                for j in range(cur):
                    divs.append(divs[j]*mul)
        return divs
    mult_lists=[[] for _ in range(T+1)]
    for v in present_small:
        divs=get_divisors(v)
        for d in divs:
            mult_lists[d].append(v)
    for lst in mult_lists:
        lst.sort()
    # now for each v
    for v in present_small:
        divs=get_divisors(v)
        idx_v=val_to_idx[v]
        for g in divs:
            limit=(T*g)//v
            lst=mult_lists[g]
            # find right boundary of values <= limit
            import bisect
            right=bisect.bisect_right(lst, limit)
            for u in lst[:right]:
                if u==v: continue
                union(idx_v, val_to_idx[u])
    # count components
    roots=set(find(i) for i in range(n))
    return len(roots)

